-- Ubicación física de los productos en el almacén central
UPDATE inventario i SET ubicacion = 'P' || lpad(p.id_categoria::text, 2, '0') || '-A' || lpad((p.id_producto % 6 + 1)::text, 2, '0')
FROM productos p, almacenes a
WHERE p.id_producto = i.id_producto AND a.id_almacen = i.id_almacen AND a.nombre = 'Almacén Central Monterrey';

